# A Level revision decks (Y12 T3): full-paper practice and answer analysis.
# Facts: ⁦9AA0⁩ specification; June 2025 question papers (P1, P3), mark schemes and examiner reports (P1, P2, P3), 2024 P2 report.
import sys, os; sys.path.insert(0, os.path.dirname(__file__))
from qlib import *
COLS = [BLUE, GREEN, ORANGE, PURPLE, TE]

def build(C):
    D = Deck(C["code"], C["foot"])
    s = D.new("🎓 A Level العربية · ⁦9AA0⁩", "", foot=False, bg="EAF5F4"); s["els"] = s["els"][:1]
    s["els"] += [T("المراجعة النهائية · السنة الثانية", 330, 92, 911, 50, 22, ORANGE, True), T(C["title"], 330, 150, 911, 130, 38, DK, True),
                 T("مواصفات Pearson Edexcel ⁦9AA0⁩ · أوراق صيف 2025", 330, 286, 911, 44, 22, TE, False), PIC("art/" + C.get("pic", "check.webp"), 48, 96, 260, 260),
                 R(L, 400, W, 220, CARD, TE, lw=2), T("🎯 هدف الحصة: " + C["goal"], 60, 412, 1160, 196, 26, DK, False, va="top")]
    s["n"] = C["src"]
    # map
    s = D.new("🗺️ خريطة الورقة", C["mapTitle"], 3, "من المواصفات وورقة الامتحان. اسأل: أين أكثر الدرجات؟ وأين أكثر الوقت؟")
    n = len(C["map"])
    for (x, w), (h, sub, col) in zip(cols(n), [(a, b, COLS[i]) for i, (a, b) in enumerate(C["map"])]): chip(s, x, 150, w, 170, h, sub, col, rv=1)
    s["els"].append(T("📌 " + C["mapNote"], L, 340, W, 120, 23, "FFFFFF", True, fill=TE, rad=True, rv=2))
    s["els"].append(T("⏱ " + C["timing"], L, 474, W, 170, 22, DK, False, fill="FFFFFF", rad=True, va="top", rv=3))
    # question types
    s = D.new("🧩 أنواع الأسئلة", "ماذا يُطلب في كل سؤال؟", 5, "اكشف صفًّا صفًّا، واسأل: ما الخطأ المتوقّع في هذا النوع؟")
    for i, (q, t, tip) in enumerate(C["qtypes"]):
        y = 150 + i * (500 // len(C["qtypes"]))
        h = 500 // len(C["qtypes"]) - 10
        s["els"] += [T(q, 1001, y, 240, h, 20, "FFFFFF", True, "center", COLS[i % 5], True), T(t, 641, y, 350, h, 19, DK, True, fill="FFFFFF", rad=True), T("💡 " + tip, L, y, 593, h, 18, DK, False, fill="FEF3C7", rad=True, rv=i + 1)]
    # strategies
    s = D.new("👩‍🏫 شاهدني أخطّط", "استراتيجية كل قسم", 6, "نمذج بصوت مسموع: ماذا أفعل في أول دقيقتين من كل قسم؟")
    for i, (h, b) in enumerate(C["strat"]):
        x, w = cols(2)[i % 2]; card(s, x, 150 + (i // 2) * 250, w, 236, h, b, COLS[i % 5], 20, rv=i + 1, hsize=23)
    # examiner
    s = D.new("⚠️ من تقارير الممتحنين", C["exTitle"], 4, "من تقرير الممتحنين الرسمي. اسأل كل طالب: أيّ نقطة تخصّني؟")
    c = cols(2)
    card(s, c[0][0], 150, c[0][1], 440, "✅ ما فعله الأقوياء", "\n".join("• " + x for x in C["good"]), GREEN, 20, rv=1, hsize=24)
    card(s, c[1][0], 150, c[1][1], 440, "❌ ما أضعف الإجابات", "\n".join("• " + x for x in C["weak"]), RED, 20, rv=2, hsize=24)
    # mark scheme
    s = D.new("📏 أصحّح بنفسي", C["msTitle"], 4, "يستعمل الطلاب هذه المعايير لتصحيح إجاباتهم في التدريب الكامل.")
    for i, (h, m, b) in enumerate(C["ms"]):
        x, w = cols(len(C["ms"]))[i]
        s["els"] += [T(h, x, 150, w, 70, 21, "FFFFFF", True, "center", COLS[i], True), T(m, x, 228, w, 50, 24, COLS[i], True, "center", "FFFFFF", True, rv=1),
                     T(b, x, 288, w, 350, 19, DK, False, fill="FFFFFF", rad=True, va="top", rv=2)]
    # practice protocol
    s = D.new("📝 التدريب الكامل", "قبل الحصة وفي أثنائها وبعدها", 5, "التدريب الكامل يكون بورقة حقيقية من موقع Pearson وبشروط الامتحان.")
    for i, (h, b) in enumerate(C["protocol"]):
        x, w = cols(4)[i]; chip(s, x, 160, w, 250, h, b, COLS[i], rv=i + 1)
    s["els"].append(T("📚 " + C["papersNote"], L, 440, W, 200, 21, DK, False, fill="FFFFFF", rad=True, va="top", rv=5))
    # error log model
    s = D.new("🔍 أحلّل إجاباتي", "سجلّ الأخطاء: نموذج", 6, "نمذج صفًّا، ثم يملأ كل طالب ثلاثة صفوف من ورقته.")
    hd = ["السؤال", "ما حدث", "السبب", "العلاج"]
    xs = [(941, 300), (601, 330), (321, 270), (L, 273)]
    for (x, w), h in zip(xs, hd): s["els"].append(T(h, x, 150, w, 50, 21, "FFFFFF", True, "center", TE, True))
    for r, row in enumerate(C["log"]):
        y = 210 + r * 110
        for (x, w), t in zip(xs, row): s["els"].append(T(t, x, y, w, 100, 18, DK, False, fill="FFFFFF", rad=True, rv=r + 1))
    s["els"].append(T("💡 الخطأ الذي يتكرّر مرتين يصبح أولوية المراجعة.", L, 550, W, 60, 21, "FFFFFF", True, "center", PURPLE, True, rv=4))
    # where to practise
    s = D.new("🧭 أين أتدرّب في حراء؟", "ورش الامتحان المرتبطة بهذه الورقة", 3, "اذكر للطلاب أن الورش فيها نماذج وإجابات مخفية للكشف بعد المحاولة.")
    for i, (h, b) in enumerate(C["ws"]):
        x, w = cols(2)[i % 2]; card(s, x, 150 + (i // 2) * 160, w, 146, h, b, COLS[i % 5], 19, rv=i + 1, hsize=21)
    # groups
    s = D.new("🚀 تحدّي المستويات", "مهام المجموعات", 10, "وزّع المستويات حسب نتائج التدريب الكامل.")
    for i, ((task, model), (lv, col)) in enumerate(zip(C["groups"], [("مبتدئ", BLUE), ("متطوّر", GREEN), ("متمكّن", PURPLE)])):
        x, w = cols(3)[i]
        s["els"] += [T(lv, x, 150, w, 54, 26, "FFFFFF", True, "center", col, True), T(task, x, 212, w, 190, 20, DK, False, fill="FFFFFF", rad=True, va="top"),
                     T("✅ " + model, x, 412, w, 232, 19, "FFFFFF", True, fill=col, rad=True, va="top", rv=1)]
    # exit
    s = D.new("🎟️ تذكرة الخروج", "ثلاثة أسئلة قبل الجرس", 3, "فرديًّا، ثم اكشف الإجابات للتصحيح الذاتي.")
    for i, (q, a) in enumerate(C["exit"]):
        y = 150 + i * 165
        s["els"] += [T(q, L, y, W, 66, 22, DK, True, fill="FFFFFF", rad=True), T("✅ " + a, L, y + 74, W, 70, 20, "FFFFFF", True, fill=GREEN, rad=True, rv=i + 1)]
    # plan
    s = D.new("🪞 خطّتي", "ماذا أراجع قبل الامتحان؟", 3, "يكتب كل طالب ثلاث أولويات من سجلّ أخطائه.")
    c = cols(2)
    card(s, c[0][0], 160, c[0][1], 300, "🪞 تعلّمتُ اليوم", C["learned"], TE, 22)
    card(s, c[1][0], 160, c[1][1], 300, "🏠 خطّة المراجعة", "\n".join(C["home"]), ORANGE, 21)
    s["els"].append(T("الدرس القادم: " + C["next"], L, 490, W, 70, 24, "FFFFFF", True, "center", PURPLE, True))
    bad = check(D.slides)
    if bad: print("OVERLAP", C["code"], bad)
    return D

